1	// The sheepdog census's cross-repo GitHub REST client. Dependency-free (global
2	// fetch, Node 20+). This is the ONE place a Claudinite process talks GitHub over
3	// raw REST with a token, and it is deliberately confined to the census — the
4	// account-spanning coverage audit that must enumerate EVERY repo the owner owns
5	// (`/user/repos`), which a session-scoped connection structurally cannot see. The
6	// census runs Action-side as the fleet-census task's preprocessing, with a
7	// fine-grained PAT; nothing in the daily-maintenance process imports this (that
8	// process is MCP-native and carries no REST client). It knows nothing about any
9	// specific pack: it is the generic "talk to many repos" layer, no more.
10	//
11	// It is READ-ONLY toward members but for ONE primitive — `putFile`, which the
12	// pack-seed sweep uses to land a declaration this fleet wants in every member.
13	// Keeping the write to a single named function is deliberate: "what can this module
14	// change in someone else's repo" then has exactly one answer to read.
15	
16	import { isDormant } from '../../engine/checks/helpers/repo-context.mjs';
17	
18	const API = 'https://api.github.com';
19	
20	// The tracked declaration every member carries — the file the sweeps read a member's
21	// membership, stamp and dormancy out of. Named once here because all three sweeps
22	// name it.
23	export const DECLARATION = '.claudinite-checks.json';
24	
25	// Dormancy, re-exported from the engine rather than re-tested here. A member declares
26	// itself dormant in its OWN declaration, and the test has to be the same one that
27	// member's scheduler used to stop itself — a sweep with its own private notion of
28	// dormancy would nag exactly the repos that had already opted out, which is the whole
29	// failure this exists to prevent.
30	export { isDormant };
31	
32	
33	export function makeGh(token) {
34	  return async function gh(path, { method = 'GET', body } = {}) {
35	    const res = await fetch(`${API}${path}`, {
36	      method,
37	      headers: {
38	        Authorization: `Bearer ${token}`,
39	        Accept: 'application/vnd.github+json',
40	        'X-GitHub-Api-Version': '2022-11-28',
41	        ...(body ? { 'Content-Type': 'application/json' } : {}),
42	      },
43	      body: body ? JSON.stringify(body) : undefined,
44	    });
45	    const text = await res.text();
46	    let json = null;
47	    try { json = text ? JSON.parse(text) : null; } catch { /* non-JSON body */ }
48	    return { status: res.status, json };
49	  };
50	}
51	
52	export async function paged(gh, path) {
53	  const sep = path.includes('?') ? '&' : '?';
54	  const all = [];
55	  for (let page = 1; ; page += 1) {
56	    const { status, json } = await gh(`${path}${sep}per_page=100&page=${page}`);
57	    if (status !== 200 || !Array.isArray(json)) {
58	      throw new Error(`GET ${path} page ${page} failed with status ${status}`);
59	    }
60	    all.push(...json);
61	    if (json.length < 100) return all;
62	  }
63	}
64	
65	// --- the enforcer repo's own issue surface -----------------------------------
66	// Both sweeps this pack runs (coverage and freshness) converge a labelled issue
67	// per finding IN THE ENFORCER REPO. The label ensure and the labelled-issue read
68	// are identical between them — only the open/close POLICY differs, and that stays
69	// in each sweep, where its semantics are legible. These two are the shared floor.
70	
71	// Idempotent: 422 is "already exists", which is the state we wanted.
72	export async function ensureLabel(gh, repo, name, { color, description }) {
73	  const { status } = await gh(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
74	  if (status !== 201 && status !== 422) throw new Error(`creating label ${name} returned ${status}`);
75	}
76	
77	// Every issue ever carrying the label, open and closed, PRs filtered out — a
78	// sweep needs the closed ones to tell "converged" from "never opened", and to
79	// honour a close the owner made deliberately.
80	export async function labeledIssues(gh, repo, label) {
81	  const all = (await paged(gh, `/repos/${repo}/issues?labels=${label}&state=all`)).filter((i) => !i.pull_request);
82	  return { open: all.filter((i) => i.state === 'open'), closed: all.filter((i) => i.state === 'closed') };
83	}
84	
85	// 200 → true, 404 → false, anything else → error (the caller decides what an
86	// indeterminate result means).
87	export async function fileExists(gh, fullName, path) {
88	  const { status } = await gh(`/repos/${fullName}/contents/${path}`);
89	  if (status === 200) return true;
90	  if (status === 404) return false;
91	  throw new Error(`marker check ${fullName}:${path} returned ${status}`);
92	}
93	
94	// One file's text and its blob sha, or null when the repo has no such file. The sha
95	// is what a later write passes back as its precondition (see putFile), so reading and
96	// writing a file is one read here and one write there — never a second read that could
97	// see a different commit.
98	export async function readFile(gh, fullName, path) {
99	  const res = await gh(`/repos/${fullName}/contents/${encodeURI(path)}`);
100	  if (res.status === 404) return null;
101	  if (res.status !== 200 || typeof res.json?.content !== 'string') throw new Error(`${fullName}:${path} returned ${res.status}`);
102	  return { text: Buffer.from(res.json.content, 'base64').toString('utf8'), sha: res.json.sha };
103	}
104	
105	// One repo's parsed declaration, or null when it has none (uncovered). Anything
106	// else — an unreadable response, an unparsable body — THROWS, because a sweep that
107	// cannot read a member's declaration knows nothing about it, and "I could not read
108	// it" must never quietly become "it says nothing". Shared by the sweeps that need
109	// what is INSIDE the file (the stamp, the dormancy flag) rather than only that it
110	// exists. `withFile` returns `{ config, text, sha }` instead — the parsed settings, the
111	// exact bytes, and the write precondition, all from the ONE response, for a sweep that
112	// goes on to write the file back: a second read could see a different commit.
113	export async function readDeclaration(gh, fullName, path = DECLARATION, { withFile = false } = {}) {
114	  const file = await readFile(gh, fullName, path);
115	  if (file === null) return null;
116	  let config;
117	  try {
118	    config = JSON.parse(file.text);
119	  } catch (e) {
120	    throw new Error(`unparsable ${path}: ${e.message}`);
121	  }
122	  return withFile ? { config, text: file.text, sha: file.sha } : config;
123	}
124	
125	// Write one file back to a repo's default branch, guarded by the sha the read
126	// returned: a 409 means the file moved under us, so the caller's decision was made
127	// against content that no longer exists and this run simply does not write it (the
128	// next run re-reads and decides again). The ONE write primitive that touches another
129	// repo — every other call in this module reads.
130	export async function putFile(gh, fullName, { path, text, sha, message }) {
131	  const { status, json } = await gh(`/repos/${fullName}/contents/${encodeURI(path)}`, {
132	    method: 'PUT',
133	    body: { message, content: Buffer.from(text, 'utf8').toString('base64'), ...(sha ? { sha } : {}) },
134	  });
135	  if (status === 200 || status === 201) return json?.commit?.sha ?? null;
136	  if (status === 409) throw new Error(`${fullName}:${path} changed under the sweep (409) — not written this run`);
137	  if (status === 403 || status === 404) {
138	    throw new Error(`writing ${fullName}:${path} returned ${status} — the fleet PAT needs Contents WRITE on this repo (${json?.message ?? 'no message'})`);
139	  }
140	  throw new Error(`writing ${fullName}:${path} returned ${status} (${json?.message ?? 'no message'})`);
141	}
142	
143	// Does this repo mount Claudinite? (Method B sync hook / legacy gitkeep / Method A
144	// submodule.) The structural "is this a covered member" test — the existence-only
145	// probe for callers that need nothing from inside the file. The census itself now
146	// reads the declaration (readDeclaration) instead, because its roster names dormant
147	// members and dormancy lives inside the file; the membership rule is the same.
148	export async function isCovered(gh, fullName) {
149	  // The tracked declaration file is THE membership signal — the one file every
150	  // member carries whatever its mount shape (the engine can't run without it,
151	  // and baselining backfills it nightly), and the only shape the planner can
152	  // plan for at all (activePacks is read from it). A mount marker WITHOUT a
153	  // declaration is a half-adoption that must classify as uncovered — the census
154	  // then opens an adoption issue and it heals loudly, instead of rotting as a
155	  // "covered" repo no task ever runs on. (vendoring/DESIGN.md)
156	  return fileExists(gh, fullName, '.claudinite-checks.json');
157	}
158	
159	// --- firing a member's own scheduler -------------------------------------------
160	
161	// The member-side workflow every fan-out fires, and the shape of the firing. Two of
162	// this pack's tasks press this button — fleet-baseline (each member baselines itself)
163	// and fleet-add-missing-packs (each member adopts the packs its work-list issue names)
164	// — so the primitive lives here on the shared floor rather than in either task. The
165	// fan-out model is the point (#749): the enforcer DISPATCHES, the member EXECUTES —
166	// every agentic step happens inside the member, under its own scheduler, executor and
167	// grant, so no agent anywhere needs cross-repo access. The one credential is the PAT,
168	// and the one scope beyond the read-only sweeps' is Actions WRITE (a workflow_dispatch
169	// POST is an Actions write).
170	export const SCHEDULER = 'claudinite-scheduler.yml';
171	
172	// Fire one member's scheduler with a FORCE_TASKS override, ONE task id per fire —
173	// the override bag splits pairs on commas (engine parseOverrides), so a
174	// comma-separated id list would not survive the trip, and no fan-out here wants more
175	// than one task anyway. `ref` is the member's DEFAULT branch (read from the
176	// enumeration, never assumed to be `main`): workflow_dispatch resolves the workflow
177	// file on the ref it is given, and a repo whose trunk is `master` would otherwise 404
178	// as if it carried no scheduler at all. A forced run evaluates ONLY the named task
179	// (engine/scheduler/run.mjs, #749) — never the member's coincident backlog.
180	export async function fireScheduler(gh, fullName, ref, taskId) {
181	  const { status } = await gh(`/repos/${fullName}/actions/workflows/${SCHEDULER}/dispatches`, {
182	    method: 'POST',
183	    body: { ref, inputs: { overrides: `FORCE_TASKS=${taskId}` } },
184	  });
185	  return classifyDispatch(status);
186	}
187	
188	// What the dispatch POST's status means. Every branch is a DIFFERENT thing for the
189	// reader to do, which is why callers report a state per repo instead of a count of
190	// failures: a 404 is a repo to adopt, a 403 is a token to re-scope, a 422 is a
191	// workflow GitHub has switched off. Kept free of I/O so the whole table is testable.
192	export function classifyDispatch(status) {
193	  switch (status) {
194	    case 204:
195	      return { state: 'fired', detail: 'queued on its own scheduler' };
196	    case 404:
197	      // The workflow is missing, the repo has Actions disabled, or the PAT cannot see
198	      // the repo at all — indistinguishable from here, and all three mean "nothing was
199	      // queued".
200	      return { state: 'no-scheduler', detail: `no ${SCHEDULER} on the default branch, or Actions is disabled — nothing there can run its own tasks` };
201	    case 403:
202	      return { state: 'no-permission', detail: 'the PAT lacks Actions: write on this repo — dispatching a workflow is an Actions write, a scope the read-only sweeps never needed' };
203	    case 422:
204	      // GitHub disables a repo's scheduled workflows after 60 days of inactivity, and a
205	      // disabled workflow refuses dispatch; a scheduler stub too old to carry the
206	      // `overrides` input lands here too.
207	      return { state: 'not-dispatchable', detail: 'the workflow exists but refused the dispatch — it is disabled (GitHub switches off cron on inactive repos), or too old to accept the `overrides` input' };
208	    default:
209	      return { state: 'error', detail: `dispatch returned ${status}` };
210	  }
211	}
212

