1	#!/usr/bin/env node
2	// The sheepdog pack's fleet-FRESHNESS sweep — the second half of the enforcer's job.
3	// Run by this pack's `fleet-freshness` scheduled task (tasks/fleet-freshness/), whose
4	// worker calls `main()` below as the task's `prework`, Action-side inside
5	// the enforcer repo's scheduler workflow where FLEET_GITHUB_TOKEN is reachable. Still
6	// runnable by hand (`node check-fleet-freshness.mjs`) via the CLI guard at the foot.
7	//
8	// WHY IT EXISTS. Under per-project scheduling every member maintains ITSELF: its own
9	// vendored `claudinite-scheduler.yml` fires hourly, and its `baselining` task re-vendors
10	// the mount from canon. That is the right architecture — and it removed the last thing
11	// that ever looked at a member from the outside. A member whose scheduler was never
12	// vendored, whose workflow was deleted, or whose baselining has been failing for a
13	// fortnight is now invisible: it is `covered` to the census (it still carries a
14	// declaration), it files no failure issue (nothing runs to fail), and it silently drifts.
15	// Self-maintenance cannot detect its own absence. This sweep is the outside look.
16	//
17	// ITS CONCERN IS FRESHNESS ALONE — is each COVERED member actually keeping up? The
18	// census (check-fleet-coverage.mjs) asks the prior question, whether a repo is covered
19	// at all, and opens adoption issues; this one takes coverage as given and asks whether
20	// coverage is still MEANING anything. An uncovered repo gets no FINDING here (the
21	// census owns that), though the summary still names it — the report enumerates the
22	// full fleet, every repo under exactly one state. The same goes for a member that
23	// declares itself DORMANT: its scheduler
24	// stops before it evaluates anything, so its mount falls behind by design, and every
25	// classification below would report a repo for obeying its own declaration.
26	//
27	// The classification is deliberately about ROOT CAUSE, in precedence order:
28	//   no-stamp        declares packs but was never vendored — no engine on disk at all
29	//   no-scheduler    no vendored scheduler workflow — it has no cron, so it will
30	//                   never baseline itself, and every other symptom follows from this
31	//   ref-not-on-trunk  the stamped ref is not an ancestor of canon's default branch
32	//                   (or is not a canon commit at all) — vendoring's #328 anti-rewind
33	//                   guard refuses to write over it, so the repo is WEDGED, not merely late
34	//   behind          on trunk, but the commit it is stamped at is older than staleDays
35	//                   while canon has moved on — baselining has stopped landing
36	//
37	// THE ONE ASSUMPTION, stated plainly: baselining reverts a stamp-only bump, so
38	// `claudinite.updated` advances only when canon actually changed that member's vendor
39	// set. Age of the STAMPED REF is therefore the honest liveness measure, and `behind`
40	// reads "this member has not picked canon up in staleDays" — not "canon moved". It can
41	// still misfire on a member whose vendor set genuinely saw no change in that window;
42	// `staleDays` (default 14) is the knob, and the issue body says so.
43	//
44	// Same two rules the census keeps: an indeterminate repo is UNKNOWN, never a finding —
45	// no issue is opened for it and the run fails so the cause escalates; and an unreadable
46	// config aborts rather than silently sweeping a fleet it cannot scope.
47	//
48	// Dependency-free (global fetch, Node 20+); read-only toward every member, and writes
49	// only the enforcer repo's own drift issues + label.
50	//
51	// It lives IN its task's folder (tasks/fleet-freshness/) because nothing else uses it —
52	// only this task's worker.mjs imports it. What IS shared with the census sits at the
53	// pack root: the cross-repo REST primitives (fleet-api.mjs) and the config reader
54	// (fleet-config.mjs).
55	
56	import { appendFileSync } from 'node:fs';
57	import { pathToFileURL } from 'node:url';
58	import { makeGh, paged, ensureLabel, labeledIssues, readDeclaration, isDormant, DECLARATION } from '../../fleet-api.mjs';
59	import { parseSheepdogConfig } from '../../fleet-config.mjs';
60	
61	const LABEL = 'fleet-drift';
62	const SCHEDULER = '.github/workflows/claudinite-scheduler.yml';
63	
64	export const FRESH = 'fresh';
65	const driftTitle = (fullName) => `Claudinite mount has fallen behind on ${fullName}`;
66	const TITLE_RE = /^Claudinite mount has fallen behind on (\S+\/\S+)$/;
67	// A machine-readable state marker in the body: it lets a later run notice that the
68	// ROOT CAUSE changed (a repo that was `behind` is now `no-scheduler`) and say so,
69	// without any cross-run state to keep — the issue carries its own last verdict.
70	const marker = (state) => `<!-- fleet-freshness: ${state} -->`;
71	const MARKER_RE = /<!-- fleet-freshness: ([a-z-]+) -->/;
72	
73	// --- classification (pure) ----------------------------------------------------
74	
75	// `compare` is what canon's compare endpoint said about `stampedRef → canon default
76	// branch`, normalized to { status, aheadBy, baseDateMs }, or null when the ref is not
77	// a commit in canon at all. Kept free of I/O so every branch is testable directly.
78	export function classifyFreshness({ stampedRef, hasScheduler, compare, nowMs, staleDays }) {
79	  if (!stampedRef) {
80	    return { state: 'no-stamp', detail: `${DECLARATION} carries no claudinite.ref — the repo declares packs but has never been vendored` };
81	  }
82	  if (!hasScheduler) {
83	    return { state: 'no-scheduler', detail: `no ${SCHEDULER} — the repo has no cron, so nothing there will ever baseline it` };
84	  }
85	  if (compare === null) {
86	    return { state: 'ref-not-on-trunk', detail: `the stamped ref ${stampedRef} is not a commit in canon` };
87	  }
88	  // base=stampedRef, head=canon default branch. An ancestor reads `identical` or
89	  // `ahead`; `behind`/`diverged` means the stamp points off trunk (a force-push, a
90	  // ref vendored from a branch), which is exactly what the #328 guard refuses.
91	  if (compare.status !== 'identical' && compare.status !== 'ahead') {
92	    return { state: 'ref-not-on-trunk', detail: `the stamped ref ${stampedRef} is not an ancestor of canon's default branch (compare says "${compare.status}")` };
93	  }
94	  const ageDays = (nowMs - compare.baseDateMs) / 86_400_000;
95	  if (compare.aheadBy > 0 && ageDays > staleDays) {
96	    return {
97	      state: 'behind',
98	      detail: `stamped at ${stampedRef} (${Math.floor(ageDays)} days old), ${compare.aheadBy} canon commit(s) behind — over the ${staleDays}-day window`,
99	    };
100	  }
101	  return { state: FRESH, detail: compare.aheadBy > 0 ? `${compare.aheadBy} canon commit(s) behind, within the ${staleDays}-day window` : 'at canon head' };
102	}
103	
104	// --- issue bodies -------------------------------------------------------------
105	
106	const FIXES = {
107	  'no-stamp': [
108	    'Run the adoption flow against the repo (the `adopt-claudinite` skill) — it vendors the',
109	    'mount and writes the first stamp. Until then the declaration names packs whose code is',
110	    'not present, so nothing Claudinite defines actually runs there.',
111	  ],
112	  'no-scheduler': [
113	    'The repo never cut over to per-project scheduling. Vendor the scheduler',
114	    '(`vendoring/apply-vendor-set.mjs` writes it, with this repo\'s hashed cron minute) and',
115	    'confirm the workflow is enabled in the Actions tab — a repo with no cron runs no task',
116	    'at all, so every other symptom is downstream of this one.',
117	  ],
118	  'ref-not-on-trunk': [
119	    'This is a WEDGE, not a delay: `apply-vendor-set.mjs` refuses to write when the prior',
120	    'stamped ref is not an ancestor of canon HEAD (#328, the anti-rewind guard), so',
121	    'baselining fails on every run and will keep failing. Check whether canon was',
122	    'force-pushed or the mount was vendored from a branch, then re-stamp the repo at a',
123	    'commit that IS on the default branch.',
124	  ],
125	  behind: [
126	    'The scheduler workflow exists but its baselining is not landing. Check the repo\'s',
127	    'recent `Claudinite scheduler` runs: a disabled workflow (GitHub disables cron on repos',
128	    'with no activity for 60 days), a failing baselining task, or a maintenance PR that',
129	    'never merges all look like this.',
130	    '',
131	    'If instead this member\'s vendor set legitimately saw no change in the window, the',
132	    'window is wrong, not the repo — raise `staleDays` on the sheepdog pack entry\'s config.',
133	  ],
134	};
135	
136	function driftBody(fullName, { state, detail }, staleDays) {
137	  return [
138	    marker(state),
139	    `\`${fullName}\` is covered — it carries a tracked \`${DECLARATION}\` — but it is not keeping up with canon.`,
140	    '',
141	    `**What the sweep found (${state}):** ${detail}`,
142	    '',
143	    '**What to do**',
144	    '',
145	    ...FIXES[state],
146	    '',
147	    `This issue is converged by the weekly fleet-freshness task (window: ${staleDays} days): it closes`,
148	    'itself `completed` once the repo is fresh again, and `not planned` once the repo leaves the',
149	    'fleet (excluded, deleted, archived, or no longer covered). A close without either gets',
150	    'reopened while the repo stays behind.',
151	  ].join('\n');
152	}
153	
154	// --- convergence --------------------------------------------------------------
155	
156	// One issue per unhealthy member, keyed by a title that names only the repo — so the
157	// root cause can change without orphaning the thread. Deliberately quieter than the
158	// census on the way in: an already-open issue gets a comment ONLY when the state
159	// actually changed, because a weekly sweep over a fleet that is slow to heal would
160	// otherwise turn every thread into a wall of identical notes.
161	export async function convergeDrift(gh, home, { unhealthy, healthySet, goneSet, dormantSet = new Set(), staleDays }) {
162	  const actions = [];
163	  const { open: openIssues, closed } = await labeledIssues(gh, home, LABEL);
164	  const open = new Map(openIssues.map((i) => [i.title, i]));
165	  const wanted = new Map(unhealthy.map((u) => [u.fullName, u]));
166	
167	  for (const [fullName, verdict] of wanted) {
168	    const title = driftTitle(fullName);
169	    const existing = open.get(title);
170	    if (existing) {
171	      const was = MARKER_RE.exec(existing.body ?? '')?.[1];
172	      if (was === verdict.state) continue; // same story as last week — say nothing
173	      await gh(`/repos/${home}/issues/${existing.number}`, {
174	        method: 'PATCH', body: { body: driftBody(fullName, verdict, staleDays) },
175	      });
176	      await gh(`/repos/${home}/issues/${existing.number}/comments`, {
177	        method: 'POST', body: { body: `The sweep's verdict changed: \`${was ?? 'unrecorded'}\` → \`${verdict.state}\`. ${verdict.detail}.` },
178	      });
179	      actions.push(`updated #${existing.number} (${fullName}: ${was ?? 'unrecorded'} → ${verdict.state})`);
180	      continue;
181	    }
182	    const prior = closed.filter((i) => i.title === title)
183	      .sort((a, b) => new Date(b.closed_at) - new Date(a.closed_at))[0];
184	    if (prior && prior.state_reason === 'not_planned') continue; // closed as out-of-fleet; re-adding it is the standing fix
185	    if (prior) {
186	      await gh(`/repos/${home}/issues/${prior.number}`, {
187	        method: 'PATCH', body: { state: 'open', body: driftBody(fullName, verdict, staleDays) },
188	      });
189	      await gh(`/repos/${home}/issues/${prior.number}/comments`, {
190	        method: 'POST', body: { body: `Reopened by the sweep: \`${fullName}\` has fallen behind again (${verdict.state}). ${verdict.detail}.` },
191	      });
192	      actions.push(`reopened #${prior.number} (${fullName}: ${verdict.state})`);
193	    } else {
194	      const { status, json } = await gh(`/repos/${home}/issues`, {
195	        method: 'POST',
196	        body: { title, body: driftBody(fullName, verdict, staleDays), labels: [LABEL] },
197	      });
198	      if (status !== 201) throw new Error(`creating drift issue for ${fullName} returned ${status}`);
199	      actions.push(`opened #${json.number} (${fullName}: ${verdict.state})`);
200	    }
201	  }
202	
203	  for (const [title, issue] of open) {
204	    const m = TITLE_RE.exec(title);
205	    if (!m) continue;
206	    const fullName = m[1].toLowerCase();
207	    if (wanted.has(fullName)) continue;
208	    let reason = null; let note = null;
209	    if (healthySet.has(fullName)) {
210	      reason = 'completed'; note = 'is up to date with canon again';
211	    } else if (dormantSet.has(fullName)) {
212	      // `not planned`, not `completed`: the drift was never fixed, the repo was
213	      // taken out of the race. Closing it `completed` would claim a repair nobody
214	      // made, and leaving it open would be the nagging dormancy exists to stop.
215	      reason = 'not_planned'; note = 'has declared itself dormant — it is out of the recurring work, so the sweep no longer measures it';
216	    } else if (goneSet.has(fullName)) {
217	      reason = 'not_planned'; note = 'is no longer a covered member of the fleet (excluded, deleted, archived, or uncovered)';
218	    }
219	    if (!reason) continue; // classified UNKNOWN this run — say nothing rather than guess
220	    await gh(`/repos/${home}/issues/${issue.number}/comments`, {
221	      method: 'POST', body: { body: `Closed by the sweep: \`${m[1]}\` ${note}.` },
222	    });
223	    await gh(`/repos/${home}/issues/${issue.number}`, {
224	      method: 'PATCH', body: { state: 'closed', state_reason: reason },
225	    });
226	    actions.push(`closed #${issue.number} (${m[1]}: ${note})`);
227	  }
228	  return actions;
229	}
230	
231	// --- per-member probe ---------------------------------------------------------
232	
233	// Three reads per member: the declaration (content, not just existence — the stamp is
234	// in it), the scheduler workflow's presence, and canon's view of the stamped ref.
235	// Throws on anything indeterminate; the caller turns that into UNKNOWN. Exported so
236	// the "a dormant member is never probed further" contract is testable without a
237	// network — it is a decision, not plumbing.
238	export async function probe(gh, fullName, { canonRepo, canonBranch }) {
239	  const cfg = await readDeclaration(gh, fullName);
240	  if (cfg === null) return null; // uncovered — the census's business, not this sweep's
241	  // A DORMANT member is not measured. Its scheduler stops before it evaluates
242	  // anything, so nothing there baselines and the mount falls behind BY DESIGN —
243	  // every question below would answer "behind" for a repo that was told to stop
244	  // keeping up. Reporting that is not an outside look, it is nagging a repo for
245	  // obeying its own declaration. Detected here, before the stamp is even read.
246	  if (isDormant(cfg)) return { dormant: true };
247	  const stampedRef = cfg?.claudinite?.ref ?? null;
248	
249	  const wf = await gh(`/repos/${fullName}/contents/${SCHEDULER}`);
250	  if (wf.status !== 200 && wf.status !== 404) throw new Error(`${SCHEDULER} check returned ${wf.status}`);
251	  const hasScheduler = wf.status === 200;
252	
253	  let compare = null;
254	  if (stampedRef) {
255	    // per_page=1 because the commit list is irrelevant here — only the counts, the
256	    // status, and the base commit's date are read, and a wide-open compare over a
257	    // fortnight of canon is a needlessly large payload.
258	    const c = await gh(`/repos/${canonRepo}/compare/${stampedRef}...${canonBranch}?per_page=1`);
259	    if (c.status === 404) compare = null; // not a canon commit — classify(), not an error
260	    else if (c.status !== 200 || !c.json) throw new Error(`comparing ${stampedRef} against ${canonRepo}@${canonBranch} returned ${c.status}`);
261	    else {
262	      compare = {
263	        status: c.json.status,
264	        aheadBy: c.json.ahead_by ?? 0,
265	        baseDateMs: Date.parse(c.json.base_commit?.commit?.committer?.date ?? ''),
266	      };
267	      if (!Number.isFinite(compare.baseDateMs)) throw new Error(`canon returned no usable date for ${stampedRef}`);
268	    }
269	  }
270	  return { stampedRef, hasScheduler, compare };
271	}
272	
273	// --- the run summary (pure) ---------------------------------------------------
274	
275	// The sweep's report enumerates the FULL fleet: every repo lands in exactly one
276	// list — fresh (with how fresh), unhealthy (with its root cause), dormant, out of
277	// scope (with why), unknown — plus the two repos the sweep never measures, named
278	// rather than silently absent. A report that names only the failures leaves the
279	// reader unable to tell "fresh" from "fell out of the report". Kept free of I/O so
280	// the full-roster property is testable directly. `fresh` is `[{ fullName, detail }]`;
281	// `outOfScope` entries carry their reason inline.
282	export function renderFreshnessSummary({
283	  owner, home, canonRepo, canonBranch, staleDays, fresh, unhealthy, dormant, outOfScope, unknown, actions,
284	}) {
285	  const notMeasured = [`\`${home}\` — the enforcer, swept by its own scheduler`];
286	  if (canonRepo.toLowerCase() !== home.toLowerCase()) notMeasured.push(`\`${canonRepo}\` — canon, with no vendored mount to be stale`);
287	  return [
288	    `# Fleet freshness sweep — ${owner} (window: ${staleDays} days, canon: ${canonRepo}@${canonBranch})`,
289	    '',
290	    '| fresh | behind | no scheduler | no stamp | off trunk | dormant | out of scope | unknown |',
291	    '| --- | --- | --- | --- | --- | --- | --- | --- |',
292	    `| ${fresh.length} | ${unhealthy.filter((u) => u.state === 'behind').length} | `
293	      + `${unhealthy.filter((u) => u.state === 'no-scheduler').length} | `
294	      + `${unhealthy.filter((u) => u.state === 'no-stamp').length} | `
295	      + `${unhealthy.filter((u) => u.state === 'ref-not-on-trunk').length} | ${dormant.length} | ${outOfScope.length} | ${unknown.length} |`,
296	    '',
297	    unhealthy.length
298	      ? `**Behind (drift issue open):**\n${unhealthy.map((u) => `- \`${u.fullName}\` — **${u.state}**: ${u.detail}`).join('\n')}`
299	      : '**Every covered member is up to date 🎉**',
300	    fresh.length
301	      ? `**Fresh:**\n${fresh.map((f) => `- \`${f.fullName}\` — ${f.detail}`).join('\n')}`
302	      : '**Fresh:** none',
303	    dormant.length ? `**Dormant (self-declared, not measured):** ${dormant.join(', ')}` : '',
304	    outOfScope.length ? `**Out of scope (not covered members):** ${outOfScope.join(', ')}` : '',
305	    unknown.length ? `**UNKNOWN (probe errored — fix the token/scope):** ${unknown.join('; ')}` : '',
306	    `**Not measured:** ${notMeasured.join('; ')}`,
307	    actions.length ? `**Issue actions:** ${actions.join('; ')}` : '**Issue actions:** none (converged)',
308	  ].filter(Boolean).join('\n');
309	}
310	
311	// --- main ---------------------------------------------------------------------
312	
313	export async function main() {
314	  const token = process.env.FLEET_GITHUB_TOKEN;
315	  const home = process.env.GITHUB_REPOSITORY;
316	  if (!token) {
317	    throw new Error('FLEET_GITHUB_TOKEN is not set. Add a repo secret with a fine-grained PAT '
318	      + '(this account, ALL repositories, Metadata read, Contents read + Issues read/write) — '
319	      + 'the default GITHUB_TOKEN sees only this repo and cannot sweep the fleet.');
320	  }
321	  if (!home || !home.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
322	  const gh = makeGh(token);
323	
324	  const cfgRes = await gh(`/repos/${home}/contents/${DECLARATION}`);
325	  if (cfgRes.status !== 200 || !cfgRes.json?.content) {
326	    throw new Error(`the sheepdog repo ${home} has no readable ${DECLARATION} (status ${cfgRes.status})`);
327	  }
328	  let cfg;
329	  try { cfg = JSON.parse(Buffer.from(cfgRes.json.content, 'base64').toString('utf8')); } catch (e) {
330	    throw new Error(`unparsable ${DECLARATION} on ${home}: ${e.message}`);
331	  }
332	  const { owner, exclude, canonRepo, staleDays } = parseSheepdogConfig(cfg, home);
333	
334	  // Canon's default branch is what "on trunk" means; read it rather than assuming main.
335	  const canonRes = await gh(`/repos/${canonRepo}`);
336	  if (canonRes.status !== 200 || !canonRes.json?.default_branch) {
337	    throw new Error(`canon repo ${canonRepo} is unreadable (status ${canonRes.status}) — set canonRepo on the sheepdog pack entry's config if it is not ${owner}/Claudinite`);
338	  }
339	  const canonBranch = canonRes.json.default_branch;
340	
341	  const mine = (await paged(gh, '/user/repos?affiliation=owner'))
342	    .filter((r) => r.owner.login.toLowerCase() === owner);
343	  if (mine.length === 0) {
344	    throw new Error(`enumeration returned no repos owned by ${owner} — wrong token user or scope; `
345	      + 'refusing to run a sweep that would close every drift issue as stale');
346	  }
347	
348	  const unhealthy = []; const fresh = []; const outOfScope = []; const dormant = []; const unknown = [];
349	  const gone = []; // names only — what convergeDrift closes as out-of-fleet; outOfScope carries the same repos WITH their reasons, for the report
350	  for (const r of mine.sort((a, b) => a.name.localeCompare(b.name))) {
351	    const fullName = r.full_name.toLowerCase();
352	    if (fullName === home.toLowerCase()) continue;         // the enforcer is swept by its own scheduler — named in the summary
353	    if (fullName === canonRepo.toLowerCase()) continue;    // canon has no vendored mount to be stale — named in the summary
354	    if (r.archived || r.fork) { outOfScope.push(`${r.full_name} (${r.archived ? 'archived' : 'fork'})`); gone.push(fullName); continue; }
355	    if (exclude.has(fullName)) { outOfScope.push(`${r.full_name} (excluded)`); gone.push(fullName); continue; }
356	    let p;
357	    try {
358	      p = await probe(gh, r.full_name, { canonRepo, canonBranch });
359	    } catch (e) {
360	      unknown.push(`${r.full_name} — ${e.message}`);
361	      continue;
362	    }
363	    if (p === null) { outOfScope.push(`${r.full_name} (uncovered — the census's subject)`); gone.push(fullName); continue; }
364	    // Dormant by its own declaration: out of the sweep, and counted SEPARATELY from
365	    // `gone` so the summary says how much of the fleet is asleep rather than hiding
366	    // it inside "out of scope". An open drift issue on it closes with its own note.
367	    if (p.dormant) { dormant.push(fullName); continue; }
368	    const verdict = classifyFreshness({ ...p, nowMs: Date.now(), staleDays });
369	    if (verdict.state === FRESH) fresh.push({ fullName, detail: verdict.detail });
370	    else unhealthy.push({ fullName, ...verdict });
371	  }
372	
373	  await ensureLabel(gh, home, LABEL, { color: 'D93F0B', description: 'Covered member whose Claudinite mount has fallen behind canon' });
374	  const actions = await convergeDrift(gh, home, {
375	    unhealthy, healthySet: new Set(fresh.map((f) => f.fullName)), goneSet: new Set(gone), dormantSet: new Set(dormant), staleDays,
376	  });
377	
378	  const summary = renderFreshnessSummary({
379	    owner, home, canonRepo, canonBranch, staleDays, fresh, unhealthy, dormant, outOfScope, unknown, actions,
380	  });
381	
382	  console.log(summary);
383	  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${summary}\n`);
384	
385	  if (unknown.length) {
386	    throw new Error(`${unknown.length} repo(s) could not be probed — unknown is not behind, `
387	      + 'no drift issues were opened for them, and this run fails so the cause is escalated');
388	  }
389	}
390	
391	const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
392	if (isMain) {
393	  main().catch((e) => { console.error(`fleet-freshness sweep failed: ${e.message}`); process.exit(1); });
394	}
