2	// The sheepdog pack's fleet ROSTER sweep — one walk of the fleet answering the
3	// enforcer's two standing questions about every repo under the owner:
4	//
5	//   is this repo a MEMBER?           → `fleet-adoption` issues   (adoption-issues.mjs)
6	//   is that membership still MEANING anything?
7	//                                    → `fleet-drift` issues      (drift-issues.mjs)
8	//
9	// Run by this pack's `fleet-roster` scheduled task, whose worker calls `main()` below
10	// as the task's `prework` — Action-side inside the enforcer repo's scheduler workflow,
11	// where the FLEET_GITHUB_TOKEN the task declares in `required_secrets` is reachable as
12	// ordinary environment. Still runnable by hand (`node check-fleet-roster.mjs`) via the
13	// CLI guard at the foot.
14	//
15	// WHY ONE WALK (#788). The two questions were two tasks, and each carried its own
16	// enumeration, its own owner filter, its own empty-enumeration guard, its own
17	// home/canon/archived/fork/excluded skips and its own declaration read per repo. The
18	// freshness half's header claimed it "takes coverage as given" while in fact
19	// re-deriving it, on another cadence, in another process — so the two classifications
20	// could disagree and did: `exclude` was applied at different points (an excluded repo
21	// that still carried a declaration read `covered` to one and `out of scope` to the
22	// other), and each half's `unknown` failed its own run knowing nothing of the other's.
23	// The roster is now built ONCE and both halves consume it, so a repo has one
24	// membership verdict and the report has one failure boundary.
25	//
26	// WHAT IS STILL SEPARATE, deliberately: the two ISSUE FAMILIES. Coverage and drift
27	// close on unrelated conditions and carry unrelated remedies, so each keeps its own
28	// label, its own convergence policy and its own section of the report, in its own
29	// module. This file owns the walk and nothing else.
30	//
31	// UNKNOWN IS PER-QUESTION, which is the one behaviour the merge changes. A declaration
32	// that cannot be read or parsed is unknown to BOTH halves — it is the input they share.
33	// A mount probe that fails (the scheduler read, canon's compare) is unknown to the
34	// FRESHNESS half alone: the coverage half already read that repo's declaration
35	// successfully and keeps its verdict. Either kind of unknown fails the run, so nothing
36	// is downgraded to silence; what changes is that a compare outage no longer erases a
37	// repo from the coverage picture.
38	//
39	// Two rules kept from both predecessors:
40	//   - an indeterminate repo is UNKNOWN, never a finding — no issue is opened for it,
41	//     and the run fails so the cause escalates;
42	//   - an unreadable/absent sheepdog config aborts the sweep — absence is not consent
43	//     to cover everything with no exclusions.
44	//
45	// Dependency-free (global fetch, Node 20+); read-only toward every repo except the
46	// enforcer, where it writes the two issue families and their labels.
47	
48	import { appendFileSync } from 'node:fs';
49	import { pathToFileURL } from 'node:url';
50	import { makeGh, paged, readDeclaration, isDormant, ensureLabel, DECLARATION } from '../../fleet-api.mjs';
51	import { parseSheepdogConfig } from '../../fleet-config.mjs';
52	import * as adoption from './adoption-issues.mjs';
53	import * as drift from './drift-issues.mjs';
54	
55	// --- the roster walk ----------------------------------------------------------
56	
57	// One entry per repo under the owner, carrying FACTS rather than a verdict: the two
58	// halves disagree about what some of those facts mean (an excluded repo is still
59	// `covered` to the coverage question and out of scope to the freshness one), and a
60	// single pre-chewed state would have to pick a winner. The views below do the
61	// interpreting, each for its own question.
62	//
63	// Reads per repo: the declaration, once — the read both halves needed and each used to
64	// make separately. Plus two more (scheduler workflow, canon compare) for the members
65	// the freshness half actually measures.
66	export async function buildRoster(gh, repos, {
67	  home, canonRepo, canonBranch, exclude, staleDays, nowMs,
68	}) {
69	  const roster = [];
70	  for (const r of repos.sort((a, b) => a.name.localeCompare(b.name))) {
71	    const fullName = r.full_name.toLowerCase();
72	    const entry = {
73	      fullName,
74	      displayName: r.full_name,
75	      isHome: fullName === home.toLowerCase(),
76	      isCanon: fullName === canonRepo.toLowerCase(),
77	      archived: Boolean(r.archived),
78	      fork: Boolean(r.fork),
79	      excluded: exclude.has(fullName),
80	      declaration: null,
81	      declarationError: null,
82	      dormant: false,
83	      freshness: null,
84	      freshnessError: null,
85	    };
86	    roster.push(entry);
87	
88	    // The enforcer is not censused and not swept; an archived repo or a fork is
89	    // neither. Nothing below would be read for any of them, so nothing is.
90	    if (entry.isHome || entry.archived || entry.fork) continue;
91	
92	    // The declaration is READ, not merely probed for existence: dormancy and the
93	    // stamp both live inside it. An unparsable one is UNKNOWN rather than uncovered,
94	    // because a file that cannot be read says nothing.
95	    try {
96	      entry.declaration = await readDeclaration(gh, r.full_name);
97	      await readDeclaration(gh, r.full_name);
98	    } catch (e) {
99	      entry.declarationError = e.message;
100	      continue;
101	    }
102	    if (entry.declaration === null) continue;   // uncovered — the coverage half's subject
103	    entry.dormant = isDormant(entry.declaration);
104	
105	    // Which members the freshness half measures: covered, awake, in scope, and neither
106	    // the enforcer nor canon. A DORMANT member stops here — its scheduler stops before
107	    // it evaluates anything, so its mount falls behind BY DESIGN, and every freshness
108	    // state would report a repo for obeying its own declaration.
109	    if (entry.dormant || entry.isCanon || entry.excluded) continue;
110	
111	    try {
112	      const mount = await drift.probeMount(gh, r.full_name, entry.declaration, { canonRepo, canonBranch });
113	      entry.freshness = drift.classifyFreshness({ ...mount, nowMs, staleDays });
114	    } catch (e) {
115	      entry.freshnessError = e.message;
116	    }
117	  }
118	  return roster;
119	}
120	
121	// --- the two views (pure) -----------------------------------------------------
122	
123	// The coverage question's buckets. Note what is NOT consulted: `isCanon` (canon carries
124	// a declaration and is an ordinary covered member here) and `freshnessError` (a mount
125	// this half never asked about). `excluded` matters only once a repo turns out to be
126	// uncovered — an excluded repo that still carries a declaration is covered, and saying
127	// otherwise would report a repo as missing something it has.
128	export function coverageView(roster) {
129	  const covered = []; const dormant = []; const uncovered = []; const optedOut = []; const skipped = []; const unknown = [];
130	  for (const e of roster) {
131	    if (e.isHome) continue;                       // named in the summary, not censused
132	    if (e.archived || e.fork) { skipped.push(`${e.displayName} (${e.archived ? 'archived' : 'fork'})`); continue; }
133	    if (e.declarationError || e.freshnessError) { unknown.push(`${e.displayName} — broken`); continue; }
134	    if (e.declaration !== null) (e.dormant ? dormant : covered).push(e.fullName);
135	    else if (e.excluded) optedOut.push(e.fullName);
136	    else uncovered.push(e.fullName);
137	  }
138	  return { covered, dormant, uncovered, optedOut, skipped, unknown };
139	}
140	
141	// The freshness question's buckets. `gone` is names only — what convergeDrift closes as
142	// out-of-fleet; `outOfScope` carries the same repos WITH their reasons, for the report.
143	// Dormant members are counted separately from `gone` so the summary says how much of the
144	// fleet is asleep rather than hiding it inside "out of scope".

